<section class="<?= $kind==='admin'?'admin-login-card':'container-wide section' ?>"><div class="auth-panel"><span class="eyebrow">PRAKSHI <?= $kind==='admin'?'STORE STUDIO':'FOODS' ?></span><h1 style="font-size:36px">Check your inbox.</h1><p>Enter the 6-digit code sent to <strong><?= e($maskedEmail) ?></strong>. It expires in 10 minutes.</p><?php if(isset($_SESSION['flash'])): [$text,$type]=$_SESSION['flash'];unset($_SESSION['flash']); ?><div class="alert alert-<?= e($type) ?>" role="status"><?= e($text) ?></div><?php endif ?><form action="<?= e(url($verifyRoute)) ?>" method="post"><?= csrf() ?><label for="otp">Verification code<input id="otp" class="form-control" type="text" name="otp" inputmode="numeric" autocomplete="one-time-code" pattern="[0-9]{6}" maxlength="6" minlength="6" required autofocus style="font-size:26px;letter-spacing:8px;text-align:center"></label><button class="btn btn-primary w-100">Verify & continue</button></form><form action="<?= e(url($resendRoute)) ?>" method="post" class="mt-4"><?= csrf() ?><button class="text-button">Send a new code</button><p class="small mt-2">Allow 60 seconds before requesting another code. Check your spam folder too.</p></form><a class="text-link" href="<?= e(url($kind==='admin'?'admin/login':'login')) ?>">Use a different account</a><p class="small mt-4">Need help? <a href="mailto:<?= e(config('support_email')) ?>"><?= e(config('support_email')) ?></a></p></div></section>
